// TransferService.java — naive (deadlock-prone) vs ordered + retry (safe)
package com.nbi.db;

public class TransferService {

    // NAIVE: lock source then target in REQUEST order -> cycle possible.
    public void transferNaive(Account from, Account to, double amt) {
        from.lock.lock();                        // A locks row 1
        pause();                                 // widen window to force the race
        to.lock.lock();                          // A waits for row 2 (B may hold it)
        try {
            from.balance -= amt; to.balance += amt;
        } finally { to.lock.unlock(); from.lock.unlock(); }
    }

    // SAFE: always lock the LOWER account id first -> consistent order, no cycle.
    public void transferOrdered(Account from, Account to, double amt) {
        Account first  = from.id < to.id ? from : to;   // consistent global order
        Account second = from.id < to.id ? to : from;
        first.lock.lock();
        second.lock.lock();
        try {
            from.balance -= amt; to.balance += amt;
        } finally { second.lock.unlock(); first.lock.unlock(); }
    }

    // RETRY wrapper: re-run a victimized transaction a bounded number of times.
    public boolean withRetry(Runnable txn, int maxAttempts) {
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                txn.run();           // the whole transaction, re-runnable from start
                return true;
            } catch (DeadlockException e) {       // SQLState 40001 / error 1213
                if (attempt == maxAttempts) return false;
                backoff(attempt);                  // short randomized backoff
            }
        }
        return false;
    }

    private void pause() { try { Thread.sleep(30); } catch (InterruptedException ignored) {} }
    private void backoff(int attempt) {
        try { Thread.sleep(10L * attempt + (long)(Math.random()*10)); } catch (InterruptedException ignored) {}
    }

    // Simulated deadlock signal from the engine.
    public static class DeadlockException extends RuntimeException {
        public DeadlockException(String m) { super(m); }
    }
}
