// Demo.java — shows ordered locking preventing deadlock + a retry example
package com.nbi.db;

import java.util.concurrent.*;

public class Demo {
    public static void main(String[] args) throws Exception {
        TransferService svc = new TransferService();
        Account a1 = new Account(1, 1000), a2 = new Account(2, 1000);

        // Two opposing transfers run concurrently using ORDERED locking -> no deadlock.
        ExecutorService pool = Executors.newFixedThreadPool(2);
        CountDownLatch latch = new CountDownLatch(2);
        pool.submit(() -> { svc.transferOrdered(a1, a2, 100); latch.countDown(); });
        pool.submit(() -> { svc.transferOrdered(a2, a1, 100); latch.countDown(); });
        latch.await(2, TimeUnit.SECONDS);
        pool.shutdown();
        System.out.printf("Ordered locking: a1=%.0f a2=%.0f  (completed, no deadlock)%n",
                a1.balance, a2.balance);

        // Retry wrapper: a transaction that deadlocks once then succeeds on retry.
        int[] calls = {0};
        boolean ok = svc.withRetry(() -> {
            calls[0]++;
            if (calls[0] == 1) throw new TransferService.DeadlockException("1213 victim");
            // second attempt succeeds
        }, 3);
        System.out.println("Retry wrapper: attempts=" + calls[0] + " finalSuccess=" + ok);
    }
}
